alter table public.website_category_reads add column if not exists cache_write_tokens integer not null default 0;
alter table public.website_category_reads add column if not exists cache_read_tokens integer not null default 0;
comment on column public.website_category_reads.cache_write_tokens is 'cache_creation_input_tokens as the API reported it: the call that wrote the rules prefix into the cache, billed at about 1.25x the input rate.';
comment on column public.website_category_reads.cache_read_tokens is 'cache_read_input_tokens as the API reported it: the rules prefix served from cache, billed at about 0.1x the input rate. Recorded apart from input_tokens because adding them together prices them at 1x, and leaving them out prices them at nothing.';
create or replace function public.category_read_spend() returns table ( model text, reads bigint, priced_reads bigint, input_tokens bigint, output_tokens bigint, cache_write_tokens bigint, cache_read_tokens bigint ) language sql stable security definer set search_path = public as $$ select r.model, count(*)::bigint, count(*) filter ( where r.input_tokens > 0 or r.cache_read_tokens > 0 or r.cache_write_tokens > 0 )::bigint, coalesce(sum(r.input_tokens), 0)::bigint, coalesce(sum(r.output_tokens), 0)::bigint, coalesce(sum(r.cache_write_tokens), 0)::bigint, coalesce(sum(r.cache_read_tokens), 0)::bigint from public.website_category_reads r group by r.model order by r.model; $$;
comment on function public.category_read_spend() is 'Tokens spent reading publisher homepages for a category, summed per model. Grouped because NICHE_MODEL is overridable and two models have two rates; the rates live in PRICING in client.ts, which is the only copy.';
revoke all on function public.category_read_spend() from public;
revoke all on function public.category_read_spend() from anon;
revoke all on function public.category_read_spend() from authenticated;
create or replace function public.category_reads_on_uncategorised() returns bigint language sql stable security definer set search_path = public as $$ select count(*)::bigint from public.website_category_reads r join public.websites w on w.id = r.website_id where w.status = 'active' and w.primary_category_id is null; $$;
comment on function public.category_reads_on_uncategorised() is 'How many still-uncategorised active listings already carry a homepage read. The backlog total minus this is what is left to read, which is not the same as the backlog total minus every read: an applied read left the backlog, a declined one did not.';
revoke all on function public.category_reads_on_uncategorised() from public;
revoke all on function public.category_reads_on_uncategorised() from anon;
revoke all on function public.category_reads_on_uncategorised() from authenticated;
